import { Router } from "express";
import { createSalon, getSalonGstSettings, getSalons, updateSalonGstSettings, } from "./salon.controller.js";
import { authenticate } from "../../middlewares/auth.middleware.js";
import { requireExactRole } from "../../middlewares/rbac.middleware.js";
const router = Router();
router.use(authenticate);
router.post("/", requireExactRole("SUPER_ADMIN"), createSalon);
router.get("/", requireExactRole("SUPER_ADMIN"), getSalons);
router.get("/gst/settings", requireExactRole("SALON_ADMIN", "SUPER_ADMIN"), getSalonGstSettings);
router.patch("/gst/settings", requireExactRole("SALON_ADMIN", "SUPER_ADMIN"), updateSalonGstSettings);
router.get("/:id/gst/settings", requireExactRole("SUPER_ADMIN"), getSalonGstSettings);
router.patch("/:id/gst/settings", requireExactRole("SUPER_ADMIN"), updateSalonGstSettings);
export default router;
